 // OMEGA-BLOCK-START
 // Computes C = A * B. C is NOT zeroed by the caller. Any number of threads may be
 // used (std::thread is available); n is any size from 1 to 2048.
+
+static constexpr int BLOCK_SIZE = 64;
+static constexpr int THREAD_COUNT = 10;
+
+// Helper to compute a tile of the result using i-k-j order for better cache utilization
+static void compute_tile(int n, int i_start, int i_end, int k_start, int k_end, 
+                         const float* A, const float* B, float* C) {
+    for (int i = i_start; i < i_end; ++i) {
+        for (int k = k_start; k < k_end; ++k) {
+            float a_ik = A[i * n + k];
+            const float* b_row_k = B + k * n;
+            float* c_row_i = C + i * n;
+            for (int j = 0; j < n; ++j) {
+                c_row_i[j] += a_ik * b_row_k[j];
+            }
+        }
+    }
+}
