+    
+    // Determine block boundaries
+    std::vector<std::pair<int, int>> row_blocks;
+    for (int i = 0; i < n; i += BLOCK_SIZE) {
+        int i_end = std::min(i + BLOCK_SIZE, n);
+        row_blocks.push_back({i, i_end});
+    }
+    
+    // Use threading to parallelize over row blocks
+    std::vector<std::thread> threads;
+    threads.reserve(THREAD_COUNT);
+    
+    // Simple work queue using atomic index
+    std::atomic<int> next_block(0);
+    
+    auto worker = [&]() {
+        while (true) {
+            int idx = next_block.fetch_add(1);
+            if (idx >= (int)row_blocks.size()) break;
+            
+            int i_start = row_blocks[idx].first;
+            int i_end = row_blocks[idx].second;
+            
+            // Process this row block with inner k-j loops
+            for (int i = i_start; i < i_end; ++i) {
+                for (int k = 0; k < n; ++k) {
+                    float a_ik = A[i * n + k];
+                    const float* b_row_k = B + k * n;
+                    float* c_row_i = C + i * n;
+                    for (int j = 0; j < n; ++j) {
+                        c_row_i[j] += a_ik * b_row_k[j];
+                    }
+                }
+            }
         }
+    };
+    
+    // Launch threads
+    for (int t = 0; t < THREAD_COUNT; ++t) {
+        threads.emplace_back(worker);
+    }
